const tok = event.data.token; if (!tok || !event.user?.isSelf) return;
const gm = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
ChatMessage.create({ content: `<b>${tok.name}</b> $у верхнего шлюза.`, whisper: gm, speaker: { alias: "Непреклонный" } });

